/**
 * Parity with the PFI Order Builder page, whose engine this module was
 * ported from. data/order-builder-golden.json holds that engine's output for
 * every part in the old calculator and the Rule Sheet examples, generated by
 * scripts/make-golden.cjs. A difference here is a change in behaviour the
 * shop would see.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { parsePartNumber, buildUnit, buildOrder } from '../src/index.ts';

interface GoldenPart {
  error?: string;
  part?: Record<string, unknown>;
  layers?: string[];
  hw?: Record<string, number>;
  inPlant?: number;
  ears?: number;
  runs?: string[];
  blanks?: string[];
}
interface GoldenOrder {
  stock: Record<string, number>;
  addon: Record<string, { pieces: number; cells: number; per: number; panels: number }>;
  cutdown: Record<string, number>;
  rips: Record<string, { qty: number; leftover: number; keepLeftover: boolean }>;
  ears: number;
  saved: Record<string, number>;
  leftoverCells: number;
  hw: Record<string, number>;
  inPlant: number;
  shelfTop8: number;
  errors: number;
}
const golden = JSON.parse(readFileSync(new URL('../data/order-builder-golden.json', import.meta.url), 'utf8')) as {
  parts: Record<string, GoldenPart>;
  orders: Record<string, GoldenOrder>;
};
const ORDERS: Record<string, Array<[string, number]>> = {
  example: [['42SQ16', 10], ['362Q12', 4], ['36SQ30', 2], ['32R12', 2], ['32HR1812', 2]],
  lengthTable: [['241Q12', 1], ['301Q12', 1], ['361Q12', 1], ['421Q12', 1], ['481Q12', 1], ['721Q12', 1], ['841Q12', 1]],
  depthTable: [['361Q8', 1], ['361Q12', 1], ['361Q16', 1], ['361Q20', 1], ['361Q24', 1], ['361Q28', 1], ['361Q30', 1], ['361Q36', 1]],
  addons: [['421Q12', 7], ['481Q12', 5], ['541Q12', 4], ['601Q12', 3], ['661Q12', 2]],
};

test('every part builds exactly as the Order Builder builds it', () => {
  let checked = 0;
  for (const [code, want] of Object.entries(golden.parts)) {
    const r = parsePartNumber(code);
    if (want.error) {
      assert.equal(r.ok, false, `${code} parsed here but not in the Order Builder`);
      continue;
    }
    assert.ok(r.ok, `${code}: ${r.ok ? '' : r.error}`);
    const u = buildUnit(r.part);
    const p = r.part;
    const summary = p.type === 'straight'
      ? { type: 'straight', shape: p.shape, length: p.length, depth: p.depth }
      : { type: 'round', kind: p.kind, depth: p.depth, ext: p.ext };
    assert.deepEqual(summary, want.part, `${code} part`);
    assert.deepEqual(u.layers.map((l) => `${l.h}${l.role[0]}`), want.layers, `${code} layers`);
    assert.deepEqual(u.hw, want.hw, `${code} hardware`);
    assert.equal(u.inPlant, want.inPlant, `${code} in-plant bolts`);
    assert.equal(u.ears.length, want.ears, `${code} ear cuts`);
    assert.deepEqual(u.runs.map((x) => `${x.L}${x.role[0]}`), want.runs, `${code} runs`);
    assert.deepEqual(u.blanks.map((b) => `${b.src}:${b.len}:${b.layer.h}${b.layer.role[0]}`).sort(), want.blanks, `${code} blanks`);
    checked++;
  }
  assert.ok(checked >= 100, `${checked} parts checked`);
});

test('every order rolls up exactly as the Order Builder rolls it up', () => {
  for (const [name, want] of Object.entries(golden.orders)) {
    const got = buildOrder(ORDERS[name].map(([code, qty]) => ({ code, qty })));
    assert.deepEqual(got.stock, want.stock, `${name} stock`);
    assert.deepEqual(got.addon, want.addon, `${name} add-ons`);
    assert.deepEqual(got.cutdown, want.cutdown, `${name} cut-downs`);
    assert.deepEqual(
      Object.fromEntries(Object.entries(got.rips).map(([k, v]) => [k, { qty: v.qty, leftover: v.leftover, keepLeftover: v.keepLeftover }])),
      want.rips,
      `${name} rips`,
    );
    assert.equal(got.ears, want.ears, `${name} ears`);
    assert.deepEqual(got.saved, want.saved, `${name} saved`);
    assert.equal(got.leftoverCells, want.leftoverCells, `${name} leftover cells`);
    assert.deepEqual(got.hw, want.hw, `${name} hardware`);
    assert.equal(got.inPlant, want.inPlant, `${name} in-plant`);
    assert.equal(got.shelfTop8, want.shelfTop8, `${name} 8" tops`);
    assert.equal(got.errors, want.errors, `${name} errors`);
  }
});
